import{parentsFor}from'./management.js';
export const importFields={clients:[['sourceId','ID ребёнка'],['name','ФИО ребёнка',true],['age','Возраст или дата рождения',true],['parentName','ФИО родителя',true],['phone','Телефон'],['email','Электронная почта'],['balance','Остаток занятий']],payments:[['sourceId','ID оплаты'],['childSourceId','ID ребёнка'],['name','ФИО ребёнка'],['date','Дата',true],['amount','Сумма, ₽',true],['credits','Количество занятий'],['method','Способ оплаты']],history:[['sourceId','ID посещения'],['childSourceId','ID ребёнка'],['name','ФИО ребёнка'],['date','Дата',true],['title','Название занятия',true],['status','Посещение / пропуск',true],['charged','Было списание']]};
const norm=x=>String(x??'').trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е').replace(/[\s_.,:()-]+/g,'');
const phone=x=>String(x||'').replace(/\D/g,'').replace(/^8(?=\d{10}$)/,'7');
const str=(x,max=100)=>String(x??'').trim().slice(0,max);
export function parseCSV(text){text=text.replace(/^\uFEFF/,'');const line=text.split(/\r?\n/,1)[0],scores=[';',',','\t'].map(d=>[d,line.split(d).length]);const sep=scores.sort((a,b)=>b[1]-a[1])[0][0];let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted||!cell)quoted=!quoted;else cell+=c}else if(c===sep&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c;if(rows.length>2001||row.length>100||cell.length>10000)throw Error('Файл слишком большой: не более 2000 строк и 100 столбцов')}if(quoted)throw Error('В CSV не закрыты кавычки');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows}
const aliases={sourceId:['id','idклиента','idученика','idплатежа','idпосещения','код'],childSourceId:['idребенка','idученика','idклиента','clientid','studentid'],name:['фио','ученик','ребенок','клиент','фиоученика','фиоребенка','имяребенка','фамилияимя'],age:['возраст','датарождения'],parentName:['родитель','фиородителя','имяродителя','контактноелицо','представитель'],phone:['телефон','телефонродителя','мобильныйтелефон'],email:['email','электроннаяпочта','почта'],balance:['остаток','остатокзанятий','балансзанятий','занятийосталось'],date:['дата','датаплатежа','датапосещения','датазанятия'],amount:['сумма','суммаоплаты','оплачено','суммаплатежа'],credits:['занятий','количествозанятий'],method:['способоплаты','типоплаты','методоплаты'],title:['занятие','названиезанятия','дисциплина','группа'],status:['статус','посещение','статуспосещения'],charged:['списано','былосписание','списание']};
export function suggestMapping(kind,headers){return Object.fromEntries(importFields[kind].map(([field])=>{const i=headers.findIndex(h=>(aliases[field]||[]).includes(norm(h)));return[field,i<0?'':String(i)]}))}
export function mappedRows(table,mapping){if(!Array.isArray(table)||table.length<2||table.length>2001)throw Error('Нужны заголовки и от 1 до 2000 строк');return table.slice(1).filter(row=>row.some(x=>x!==null&&x!==undefined&&String(x).trim())).map(row=>Object.fromEntries(Object.entries(mapping).map(([field,index])=>[field,index===''?'':row[Number(index)] instanceof Date?row[Number(index)].toISOString().slice(0,10):String(row[Number(index)]??'').trim()])))}
const number=x=>{const t=String(x??'').replace(/\s|₽|руб\.?/g,'').replace(',','.');return t===''?0:Number(t)};
function date(x){const raw=str(x),parts=raw.match(/^(\d{2})\.(\d{2})\.(\d{4})(?:\s.*)?$/),value=parts?`${parts[3]}-${parts[2]}-${parts[1]}`:raw.slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(+new Date(value+'T12:00:00Z'))||new Date(value+'T12:00:00Z').toISOString().slice(0,10)!==value)throw Error('Некорректная дата');return value}
function age(x,now){if(/^\d{1,2}$/.test(str(x)))return +x;const born=date(x),today=now.toLocaleDateString('sv-SE',{timeZone:'Asia/Yekaterinburg'});return Number(today.slice(0,4))-Number(born.slice(0,4))-(today.slice(5)<born.slice(5)?1:0)}
function stable(row){return JSON.stringify(row)}
export function planImport(state,input,now=new Date()){
 if(!['clients','payments','history'].includes(input.kind)||!Array.isArray(input.rows)||!input.rows.length||input.rows.length>2000)throw Error('Выберите тип данных и от 1 до 2000 строк');const s=structuredClone(state);s.parents=parentsFor(s);let added=0,skipped=0;const errors=[],sample=[];
 input.rows.forEach((row,i)=>{try{if(!row||typeof row!=='object'||Object.values(row).some(v=>typeof v!=='string'||v.length>500))throw Error('Некорректная строка');
  const sourceId=str(row.sourceId,100);
  if(input.kind==='clients'){
   const name=str(row.name),parentName=str(row.parentName),email=str(row.email,254),tel=str(row.phone,30),years=age(row.age,now),balance=number(row.balance);if(!name||!parentName||!Number.isInteger(years)||years<3||years>18)throw Error('Нужны ФИО ребёнка, родитель и возраст 3–18 лет');if(!tel&&!email||tel&&phone(tel).length<10||email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Укажите телефон или корректную почту родителя');if(!Number.isInteger(balance)||balance<0||balance>100000)throw Error('Остаток должен быть целым числом от 0 до 100000');
   let p=s.parents.find(p=>!p.archived&&norm(p.name)===norm(parentName)&&(tel&&phone(p.phone)===phone(tel)||email&&norm(p.email)===norm(email)));
   if(s.children.some(c=>sourceId&&c.importSource==='moyklass'&&c.importId===sourceId||norm(c.name)===norm(name)&&c.age===years&&(p?c.family===p.family:norm(c.parent)===norm(parentName)&&phone(c.phone)===phone(tel)))){skipped++;return}
   if(!p){p={id:crypto.randomUUID(),family:crypto.randomUUID(),name:parentName,phone:tel,email,archived:false};s.parents.push(p)}const c={id:crypto.randomUUID(),family:p.family,name,age:years,parent:p.name,phone:p.phone,email:p.email,balance,color:'peach',importSource:'moyklass',importId:sourceId||stable([name,years,parentName,tel,email])};s.children.push(c);sample.push({name:c.name,detail:`${years} лет · остаток ${balance}`});
  }else{
   let matches=row.childSourceId?s.children.filter(c=>c.importSource==='moyklass'&&c.importId===str(row.childSourceId)):s.children.filter(c=>norm(c.name)===norm(row.name));if(matches.length!==1)throw Error(matches.length?'Несколько детей с таким именем: используйте ID ребёнка':'Ребёнок не найден. Сначала импортируйте клиентов или проверьте ID/ФИО');const c=matches[0],day=date(row.date),list=input.kind==='payments'?s.payments:s.history;
   if(input.kind==='payments'){const amount=number(row.amount),credits=number(row.credits);if(!Number.isFinite(amount)||amount<=0||amount>1000000||!Number.isInteger(credits)||credits<0||credits>100)throw Error('Некорректная сумма или количество занятий');const marker=sourceId||stable([c.id,day,amount,credits,str(row.method)]);if(list.some(p=>p.importSource==='moyklass'&&p.importId===marker)){skipped++;return}list.push({id:crypto.randomUUID(),child:c.id,date:day,amount,credits,method:str(row.method)||'Импорт МойКласс',receipt:null,provider:'import',importSource:'moyklass',importId:marker});sample.push({name:c.name,detail:`${day} · ${amount} ₽`})}
   else{const status=norm(row.status),present=['пришел','присутствовал','посетил','был','посещение','attended','1','да'].includes(status),missed=['пропуск','небыл','отсутствовал','непришел','missed','0','нет'].includes(status);if(!present&&!missed||!str(row.title))throw Error('Нужны название занятия и статус: «Пришёл» или «Пропуск»');const marker=sourceId||stable([c.id,day,str(row.title),present]);if(list.some(h=>h.importSource==='moyklass'&&h.importId===marker)){skipped++;return}list.push({id:crypto.randomUUID(),child:c.id,date:day,title:str(row.title),status:present?'attended':'missed',charged:['1','да','true','списано'].includes(norm(row.charged)),importSource:'moyklass',importId:marker});sample.push({name:c.name,detail:`${day} · ${present?'Пришёл':'Пропуск'}`})}
  }added++;
 }catch(e){errors.push({row:i+2,message:e.message})}});
 return{state:s,report:{kind:input.kind,total:input.rows.length,added,skipped,errors,sample:sample.slice(0,8)}}
}
export function applyImport(s,input,now){const{state,report}=planImport(s,input,now);if(report.errors.length)throw Error('Импорт не выполнен. Строка '+report.errors[0].row+': '+report.errors[0].message);Object.assign(s,state);s.lastImport={...report,sample:[],at:now.toISOString()};s.activity.unshift({text:'Импорт МойКласс · добавлено '+report.added+', пропущено '+report.skipped,time:now.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Yekaterinburg'}),type:'import'});return report}
